using System;

public class CliCommandBuilder
{
    public static string BuildPublishCommand(string? projectFile, string configuration, string outputDir)
    {
        if (string.IsNullOrWhiteSpace(projectFile)) return "";
        string conf = string.IsNullOrWhiteSpace(configuration) ? "Release" : configuration.Trim();
        string outDir = string.IsNullOrWhiteSpace(outputDir) ? "./publish" : outputDir.Trim();

        return $"dotnet publish {projectFile.Trim()} -c {conf} -o {outDir}";
    }

    public static void Main()
    {
        Console.WriteLine(BuildPublishCommand("Api.csproj", "Release", "/dist"));
    }
}
